"use client"

import { Button } from "@workspace/ui/components/button"
import { Input } from "@workspace/ui/components/input"
import { Label } from "@workspace/ui/components/label"
import Link from "next/link"
import { useState } from "react"
import { TRIP_LEGS_MAX, TRIP_TITLE_MAX, type Trip } from "@/lib/trips"

interface Options {
  cities: Array<{ id: string; name: string; countryCode: string }>
  bucketItems: Array<{ id: number; title: string; city_id: string | null; planned: boolean }>
  /** Preselected via /trips?from_bucket={id}. */
  fromBucketId: number | null
}

interface LegDraft {
  key: number
  cityId: string
  nights: string
}

const selectClassName =
  "h-9 w-full rounded-4xl border border-input bg-input/30 px-3 text-base outline-none focus-visible:border-ring focus-visible:ring-[3px] focus-visible:ring-ring/50 md:text-sm"

type Status =
  | { kind: "idle" }
  | { kind: "busy" }
  | { kind: "deleted"; title: string }
  | { kind: "error"; message: string }

async function send(path: string, init?: RequestInit): Promise<{ ok: boolean; data: unknown }> {
  const response = await fetch(path, {
    ...init,
    headers: init?.body ? { "content-type": "application/json" } : undefined,
  })
  return { ok: response.ok, data: await response.json() }
}

function errorMessage(data: unknown, fallback: string): string {
  const message = (data as { error?: { message?: unknown } } | null)?.error?.message
  return typeof message === "string" ? message : fallback
}

let nextKey = 0

export function TripsManager({ initialTrips, options }: { initialTrips: Trip[]; options: Options }) {
  const cityName = new Map(options.cities.map((c) => [c.id, c.name]))
  const preselected = options.bucketItems.find((item) => item.id === options.fromBucketId)

  const [trips, setTrips] = useState(initialTrips)
  const [title, setTitle] = useState(preselected?.title ?? "")
  const [startDate, setStartDate] = useState("")
  const [legs, setLegs] = useState<LegDraft[]>(() => [
    { key: nextKey++, cityId: preselected?.city_id ?? "", nights: "2" },
  ])
  const [fromBucket, setFromBucket] = useState(preselected ? String(preselected.id) : "")
  const [status, setStatus] = useState<Status>({ kind: "idle" })

  const totalNights = legs.reduce((sum, leg) => sum + (Number.parseInt(leg.nights, 10) || 0), 0)

  function updateLeg(key: number, change: Partial<LegDraft>) {
    setLegs((current) => current.map((leg) => (leg.key === key ? { ...leg, ...change } : leg)))
  }

  async function refresh() {
    const { ok, data } = await send("/api/trips")
    if (ok) setTrips((data as { trips: Trip[] }).trips)
  }

  async function onCreate(event: React.FormEvent<HTMLFormElement>) {
    event.preventDefault()
    if (!title.trim()) return setStatus({ kind: "error", message: "Give the trip a title." })
    if (!startDate) return setStatus({ kind: "error", message: "Pick a start date." })
    if (legs.some((leg) => !leg.cityId)) {
      return setStatus({ kind: "error", message: "Pick a city for every leg." })
    }
    if (legs.some((leg) => !/^[1-9]\d*$/.test(leg.nights.trim()))) {
      return setStatus({ kind: "error", message: "Nights must be a whole number, at least 1." })
    }
    setStatus({ kind: "busy" })
    try {
      const { ok, data } = await send("/api/trips", {
        method: "POST",
        body: JSON.stringify({
          title,
          start_date: startDate,
          legs: legs.map((leg) => ({ city_id: leg.cityId, nights: Number(leg.nights.trim()) })),
          from_bucket_id: fromBucket ? Number(fromBucket) : null,
        }),
      })
      if (!ok) {
        return setStatus({ kind: "error", message: errorMessage(data, "Could not create the trip.") })
      }
      await refresh()
      setTitle("")
      setStartDate("")
      setLegs([{ key: nextKey++, cityId: "", nights: "2" }])
      setFromBucket("")
      setStatus({ kind: "idle" })
    } catch {
      setStatus({ kind: "error", message: "Could not reach the server." })
    }
  }

  // No confirmation: deletes are soft and undoable.
  async function onDelete(trip: Trip) {
    setTrips((current) => current.filter((t) => t.id !== trip.id))
    try {
      const { ok, data } = await send(`/api/trips/${trip.id}`, { method: "DELETE" })
      if (!ok) {
        setStatus({ kind: "error", message: errorMessage(data, "Could not delete the trip.") })
        await refresh()
        return
      }
      setStatus({ kind: "deleted", title: trip.title })
    } catch {
      setStatus({ kind: "error", message: "Could not reach the server." })
      await refresh()
    }
  }

  async function onUndo() {
    setStatus({ kind: "busy" })
    try {
      const { ok, data } = await send("/api/undo", { method: "POST" })
      if (!ok) return setStatus({ kind: "error", message: errorMessage(data, "Nothing to undo.") })
      await refresh()
      setStatus({ kind: "idle" })
    } catch {
      setStatus({ kind: "error", message: "Could not reach the server." })
    }
  }

  return (
    <div className="flex flex-col gap-6 text-sm">
      <form
        data-testid="trips-form"
        onSubmit={onCreate}
        noValidate
        className="flex flex-col gap-4 rounded-2xl border border-border bg-card p-6"
      >
        <div className="grid gap-4 sm:grid-cols-[1fr_auto]">
          <div className="flex flex-col gap-2">
            <Label htmlFor="trip_title">Trip name</Label>
            <Input
              id="trip_title"
              data-testid="trip-title"
              placeholder="e.g. Two weeks in Vietnam"
              maxLength={TRIP_TITLE_MAX}
              value={title}
              onChange={(e) => setTitle(e.target.value)}
            />
          </div>
          <div className="flex flex-col gap-2">
            <Label htmlFor="trip_start">Start date</Label>
            <Input
              id="trip_start"
              data-testid="trip-start-date"
              type="date"
              value={startDate}
              onChange={(e) => setStartDate(e.target.value)}
            />
          </div>
        </div>

        <fieldset className="flex flex-col gap-2">
          <legend className="mb-2 font-medium">
            Legs · {totalNights} {totalNights === 1 ? "night" : "nights"}
          </legend>
          {legs.map((leg, i) => (
            <div key={leg.key} data-testid={`trip-leg-${i}`} className="flex items-center gap-2">
              <select
                aria-label={`Leg ${i + 1} city`}
                data-testid={`trip-leg-city-${i}`}
                className={selectClassName}
                value={leg.cityId}
                onChange={(e) => updateLeg(leg.key, { cityId: e.target.value })}
              >
                <option value="">Choose a city</option>
                {options.cities.map((city) => (
                  <option key={city.id} value={city.id}>
                    {city.name} · {city.countryCode}
                  </option>
                ))}
              </select>
              <Input
                aria-label={`Leg ${i + 1} nights`}
                data-testid={`trip-leg-nights-${i}`}
                className="w-20"
                inputMode="numeric"
                value={leg.nights}
                onChange={(e) => updateLeg(leg.key, { nights: e.target.value })}
              />
              <span className="text-muted-foreground">nights</span>
              <Button
                type="button"
                variant="ghost"
                size="sm"
                aria-label={`Remove leg ${i + 1}`}
                disabled={legs.length === 1}
                onClick={() => setLegs((current) => current.filter((l) => l.key !== leg.key))}
              >
                Remove
              </Button>
            </div>
          ))}
          <div>
            <Button
              type="button"
              variant="outline"
              size="sm"
              data-testid="trip-add-leg"
              disabled={legs.length >= TRIP_LEGS_MAX}
              onClick={() =>
                setLegs((current) => [...current, { key: nextKey++, cityId: "", nights: "2" }])
              }
            >
              Add a leg
            </Button>
          </div>
        </fieldset>

        {options.bucketItems.length > 0 && (
          <div className="flex flex-col gap-2">
            <Label htmlFor="trip_bucket">From your bucket list (optional)</Label>
            <select
              id="trip_bucket"
              data-testid="trip-from-bucket"
              className={selectClassName}
              value={fromBucket}
              onChange={(e) => setFromBucket(e.target.value)}
            >
              <option value="">None</option>
              {options.bucketItems.map((item) => (
                <option key={item.id} value={item.id}>
                  {item.title}
                  {item.planned ? " (planned)" : ""}
                </option>
              ))}
            </select>
          </div>
        )}

        <div className="flex justify-end">
          <Button type="submit" data-testid="trip-add" disabled={status.kind === "busy"}>
            Create trip
          </Button>
        </div>
      </form>

      <div
        data-testid="trips-status"
        role="status"
        className="flex min-h-9 items-center justify-between gap-4"
      >
        <p className={status.kind === "error" ? "text-destructive" : "text-muted-foreground"}>
          {status.kind === "busy" && "Working…"}
          {status.kind === "deleted" && `Deleted “${status.title}”.`}
          {status.kind === "error" && status.message}
        </p>
        {status.kind === "deleted" && (
          <Button variant="outline" size="sm" data-testid="trips-undo" onClick={onUndo}>
            Undo
          </Button>
        )}
      </div>

      {trips.length === 0 ? (
        <p data-testid="trips-empty" className="text-muted-foreground">
          No trips yet.
        </p>
      ) : (
        <ul data-testid="trips" className="flex flex-col gap-3">
          {trips.map((trip) => (
            <li
              key={trip.id}
              data-testid={`trip-${trip.id}`}
              className="flex items-start justify-between gap-4 rounded-2xl border border-border bg-card p-4"
            >
              <Link href={`/trips/${trip.id}`} className="flex min-w-0 flex-col gap-1 hover:underline">
                <span className="font-medium">{trip.title}</span>
                <span className="text-muted-foreground">
                  {trip.start_date} → {trip.end_date} · {trip.nights}{" "}
                  {trip.nights === 1 ? "night" : "nights"} ·{" "}
                  {trip.legs.map((leg) => cityName.get(leg.city_id) ?? leg.city_id).join(" → ")}
                </span>
              </Link>
              <Button
                variant="ghost"
                size="sm"
                data-testid={`trip-delete-${trip.id}`}
                aria-label={`Delete ${trip.title}`}
                onClick={() => onDelete(trip)}
              >
                Delete
              </Button>
            </li>
          ))}
        </ul>
      )}
    </div>
  )
}
