"use client"

import { Button } from "@workspace/ui/components/button"
import { useRouter } from "next/navigation"
import { useState, useTransition } from "react"
import type { Suggestion, SuggestionAction } from "@/lib/suggestions"

interface Props {
  advice: Suggestion[]
}

const KIND_LABEL: Record<string, string> = {
  lighten_day: "Lighten the day",
  closed_venue: "Closed that day",
  over_budget: "Over budget",
  weather_risk: "Weather risk",
}

function fixLabel(action: SuggestionAction): string {
  switch (action.type) {
    case "remove_item":
      return `Remove ${action.name} from day ${action.day_index}`
    case "move_item":
      return `Move ${action.name} to day ${action.to_day_index}`
    case "replace_item":
      return `Swap ${action.name} for ${action.replacement.name} at ${action.start_time}`
    case "add_activity":
      return `Add ${action.name} on day ${action.day_index}`
  }
}

/**
 * The curation advisor: what could be better about the trip. Each piece of
 * advice is numbered from 1 in list order (advice-{kind}-{n}, advice-apply-{n})
 * and applied via POST /api/suggestions/{id}/apply.
 */
export function AdviceList({ advice }: Props) {
  const router = useRouter()
  const [pending, startTransition] = useTransition()
  const [error, setError] = useState<string | null>(null)

  async function apply(id: number) {
    try {
      const response = await fetch(`/api/suggestions/${id}/apply`, { method: "POST" })
      if (!response.ok) {
        const data = (await response.json()) as { error?: { message?: string } }
        setError(data.error?.message ?? "Something went wrong.")
      } else {
        setError(null)
      }
      startTransition(() => router.refresh())
    } catch {
      setError("Could not reach the server.")
    }
  }

  return (
    <section aria-label="Advice" data-testid="advice" className="flex flex-col gap-3">
      <h2 className="text-base font-semibold">What could be better</h2>
      {advice.length === 0 ? (
        <p data-testid="advice-empty" className="text-muted-foreground">
          Nothing to improve right now.
        </p>
      ) : (
        <ol className="flex flex-col gap-2">
          {advice.map((suggestion, i) => {
            const n = i + 1
            return (
              <li
                key={suggestion.id}
                data-testid={`advice-${suggestion.kind}-${n}`}
                data-suggestion-id={suggestion.id}
                className="flex items-start justify-between gap-3 rounded-xl border px-3 py-2"
              >
                <div className="flex min-w-0 flex-col gap-0.5">
                  <span className="font-medium">
                    {KIND_LABEL[suggestion.kind] ?? suggestion.kind}{" "}
                    <span className="text-muted-foreground">
                      · {fixLabel(suggestion.action)}
                    </span>
                  </span>
                  <span className="text-muted-foreground">{suggestion.reason}</span>
                </div>
                <Button
                  variant="outline"
                  size="sm"
                  data-testid={`advice-apply-${n}`}
                  disabled={pending}
                  onClick={() => apply(suggestion.id)}
                >
                  Apply
                </Button>
              </li>
            )
          })}
        </ol>
      )}
      {error && (
        <p data-testid="advice-error" className="text-destructive">
          {error}
        </p>
      )}
    </section>
  )
}
